(
  $parseField := function($field) {(
    $baseTypeMatch := $match($field.type, /\[?(\w+)!?\]?!?/);
    $baseType := $baseTypeMatch.groups[0];

    $baseFieldName := $match($field.name, /(\w+)Id$/).groups[0];
    $baseField := $state.context.component.model.fields[name=$baseFieldName];
    $baseFieldType := $match($baseField.type, /\[?(\w+)!?\]?!?/).groups[0];

    {
      "field": $field,
      "isList": $contains($field.type, "["),
      "isRequired": $contains($field.type, "!"),
      "baseType": $baseType,
      "baseTypeModel": $executeTransform("getModelByName", {
        "api": $state.context.parameters.api,
        "name": $baseType
      }),
      "baseField": {
        "isList": $contains($baseField.type, "["),
        "isRequired": $contains($baseField.type, "!"),
        "fieldName": $baseFieldName,
        "field": $baseField,
        "baseType": $baseFieldType,
        "baseTypeModel": $executeTransform("getModelByName", {
          "api": $state.context.parameters.api,
          "name": $baseFieldType
        })
      },
      "updateField": updateModel.fields[name=$field.name]
    }
  )}; 

  /* Parse field types. */
  $parsedFields := $map(fields, $parseField);

  /* Filter out any fields that are the id, lists, or another field's baseField. */
  $filter($parsedFields, function($field) {
    $not($field.name = 'id') and $not($field.isList) and $not($exists($parsedFields[baseField.fieldName=$field.field.name]))
  })
)

(
  $dataPath := field.name;
  $label := $startCase(field.name);

  $scalarMap := {
    "String": {
      "type": field.name = "description" or field.name = "note" ? 'markdown' : 'text'
    },
    "Password": {
      "type": "password"
    },
    "Email": {
      "type": 'text'
    },
    "Boolean": {
      "type": 'checkbox'
    },
    "DateTime": {
      "type": 'datetime'
    },
    "Date": {
      "type": 'date'
    },
    "Time": {
      "type": 'time'
    },
    "Int": {
      "name": field.name,
      "label": $label,
      "dataPath": $dataPath,
      "type": 'integer'
    },
    "Float": {
      "type": 'float'
    },
    "Measure": {
      "type": 'measure',
      "query": {
        "fields": [
          $dataPath & '.value',
          $dataPath & '.unit.code',
          $dataPath & '.unit.id'

        ]
      }
    },
    "RatioMeasure": {
      "type": 'ratioMeasure',
      "query": {
        "fields": [
          $dataPath & '.numeratorValue',
          $dataPath & '.numeratorUnit.code',
          $dataPath & '.numeratorUnit.id',
          $dataPath & '.denominatorUnit.code',
          $dataPath & '.denominatorUnit.id'

        ]
      }
    },
    "Address": {
      "type": 'address',
        "query": {
        "fields": [
          $dataPath & ".lines",
          $dataPath & ".city",
          $dataPath & ".state",
          $dataPath & ".country",
          $dataPath & ".postalCode"
        ]
      }
    },
    "JSON": {
      "type": 'json'
    },
    "JSONObject": {
      "type": 'json'
    }
  };

  $format := $lookup($scalarMap, baseType);

  $merge([
    { 
      "name": field.name,
      "description": field.description,
      "label": $label,
      "type": "text",
      "dataPath": $dataPath,
      "validation": {
        "required": isRequired and $not($exists(field.metadata.mfgx.defaultValue))
      },
      "query": {
        "fields": [$dataPath]
      }
    },
    $format    
  ])
)

(
  $labelField := $coalesce([baseField.baseTypeModel.metadata.mfgx.labelField, "id"]);

  {
    "name": baseField.field.name,
    "description": baseField.field.description,
    "label": $startCase(baseField.field.name),
    "labelField": $labelField,
    "labelPath": $labelField,
    "additionalFields": $labelField,
    "type": 'combobox',
    "dataPath": baseField.field.name,
    "target": {
      "dataPath": field.name
    },
    "api": $state.context.parameters.api,
    "queryType": baseField.baseType,
    "linkTarget": {
      "__transform": '"/' 
        & baseField.baseTypeModel.metadata.mfgx.module.group.id 
        & '/' 
        & baseField.baseTypeModel.metadata.mfgx.module.id 
        & '/'
        & $pluralize($lowerFirst(baseField.baseType),'en')
        & '/'
        & '" & data.'
        & baseField.field.name
        & '.id'
    },
    "query": {
      "fields": [
        baseField.field.name & '.id', 
        baseField.field.name & '.' & $labelField
      ]
    },
    "validation": {
      "required": isRequired and $not($exists(field.metadata.mfgx.defaultValue))
    }
  }
)

(
  $labelField := $coalesce([baseField.baseTypeModel.metadata.mfgx.labelField, "id"]);

  {
    "name": baseField.field.name,
